//! The native desktop shell.
//!
//! # One UI, one backend
//!
//! This is not a second application. It starts the same `devd-server` used by
//! `devd ui`, against the same capability registry, and points a Tauri webview
//! at the same HTML, CSS and JavaScript. There are no Tauri commands, no plugin
//! shell, and no privileged bridge into the page. The frontend talks to the
//! loopback API exactly as it does in a browser; the only difference is that the
//! window is native.
//!
//! # Security boundary
//!
//! * The bearer token is generated by the server and injected into the HTML over
//!   loopback. It is never written to disk and never placed in a command line.
//! * Top-level navigation away from the devd origin is refused and handed to the
//!   operating system's browser. A previewed site lives in the existing
//!   sandboxed iframe and cannot navigate the shell.
//! * No `tauri-plugin-shell`, filesystem or process API is registered. A remote
//!   origin therefore has no IPC surface to reach even if its page is hostile.
//! * PTYs and project processes are owned by this process and stopped on exit.
//!
//! # The one thing the shell adds
//!
//! A browser page cannot open the operating system's folder dialog. The shell
//! can, so it supplies the server with a [`FolderPicker`]. The dialog returns
//! a path and nothing else: it cannot read a file, run a program or reach the
//! registry. Everything that happens with the path afterwards goes through the
//! ordinary capability API, where the permission checks live.

use std::sync::atomic::{AtomicBool, AtomicU16, Ordering};
use std::sync::{mpsc, Arc, Mutex};
use std::time::Duration;

use devd_bootstrap::Bootstrap;
use devd_core::capability::{Actor, Ctx, Surface};
use devd_server::{Bound, Options};
use tauri::menu::{CheckMenuItem, IsMenuItem, Menu, MenuItem, PredefinedMenuItem, Submenu};
use tauri::Wry;
use tauri::tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent};
use tauri::{Manager, RunEvent, WebviewUrl, WebviewWindowBuilder};

pub mod picker;
type Shutdown = Arc<Mutex<Option<tokio::sync::watch::Sender<bool>>>>;

/// Launch the desktop application.
pub fn run() {
    startup_log("devd-desktop starting");
    let boot = match Bootstrap::discover() {
        Ok(boot) => boot,
        Err(e) => {
            let message = format!(
                "devd could not start its backend.\n\n{e}\n\nDEVD_HOME: {}",
                std::env::var("DEVD_HOME").unwrap_or_else(|_| "(platform default)".into())
            );
            startup_log(&format!("backend bootstrap failed: {message}"));
            show_error(message);
            return;
        }
    };
    // When the resident process is already running this window is its client:
    // it loads the interface that process serves and owns no background work.
    let (claim, client) = match devd_server::attach_or_claim(&boot.paths, "ui") {
        Ok(devd_server::Attach::Client { port, .. }) => (None, Some(port)),
        Ok(devd_server::Attach::Own(claim)) => {
            boot.agents.resume(&boot.paths, &boot.store, &boot.registry);
            if devd_bootstrap::start_ops(&boot.paths, &boot.store, &boot.settings, &boot.events) {
                devd_bootstrap::start_reconcile(&boot.paths, &boot.store, &boot.settings, &boot.events);
                devd_bootstrap::start_supervisor(
                    &boot.paths,
                    &boot.store,
                    &boot.settings,
                    &boot.events,
                    &boot.registry,
                );
            }
            (Some(claim), None)
        }
        Err(e) => {
            startup_log(&format!("cannot attach or claim the instance: {e}"));
            show_error(format!("devd could not start.

{e}"));
            return;
        }
    };
    if let Err(e) = run_with(boot, claim, client) {
        startup_log(&format!("window/backend failed: {e}"));
        show_error(format!("devd could not open its window.\n\n{e}"));
    }
}

/// Append a startup diagnostic where a user can find it.
///
/// The release binary has no console (`windows_subsystem = "windows"`), so a
/// startup failure would otherwise be an invisible process that exits. The log
/// lives beside the state, never in the repository.
fn startup_log(message: &str) {
    let root = std::env::var_os("DEVD_HOME")
        .map(std::path::PathBuf::from)
        .or_else(|| {
            std::env::var_os("LOCALAPPDATA")
                .map(std::path::PathBuf::from)
                .map(|p| p.join("devd"))
        });
    if let Some(root) = root {
        let _ = std::fs::create_dir_all(&root);
        let path = root.join("desktop.log");
        if let Ok(mut file) = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)
        {
            use std::io::Write as _;
            let _ = writeln!(file, "{} {message}", chrono::Utc::now().to_rfc3339());
        }
    }
}

fn run_with(
    boot: Bootstrap,
    claim: Option<devd_core::daemon::Claim>,
    client: Option<u16>,
) -> tauri::Result<()> {
    let claim = Arc::new(Mutex::new(claim));
    let (ready_tx, ready_rx) = mpsc::channel::<Result<Bound, String>>();
    let (shutdown_tx, shutdown_rx) = tokio::sync::watch::channel(false);
    let shutdown: Shutdown = Arc::new(Mutex::new(Some(shutdown_tx)));
    // The hidden-icons tray keeps devd alive after the window is closed, the
    // way a background service behaves. If the tray cannot be built the old
    // behaviour (closing the window stops the process) is kept rather than
    // leaving an invisible process.
    let tray_ready = Arc::new(AtomicBool::new(false));
    let data_dir = boot.paths.root().display().to_string();

    // What the tray lists, read once at start: the menu is a snapshot, and the
    // actions themselves go to the live API.
    let tray_projects: Vec<(String, String)> = boot
        .store
        .list_stack_projects()
        .unwrap_or_default()
        .into_iter()
        .map(|p| (p.name, p.path))
        .collect();
    let tray_sites: Vec<(String, String)> = boot
        .store
        .list_sites()
        .unwrap_or_default()
        .into_iter()
        .map(|s| (s.name, s.root))
        .collect();
    let tray_services: Vec<String> = devd_services::list(&Ctx {
        store: boot.store.clone(),
        paths: Arc::new(boot.paths.clone()),
        settings: boot.settings.clone(),
        events: boot.events.clone(),
        actor: Actor::human(Surface::Gui),
        run: None,
        dry_run: false,
    })
    .unwrap_or_default()
    .into_iter()
    .filter(|s| s.installed)
    .map(|s| s.name)
    .collect();

    let registry = boot.registry.clone();
    let workspace = boot.workspace.clone();
    let ctx = Ctx {
        store: boot.store.clone(),
        paths: Arc::new(boot.paths.clone()),
        settings: boot.settings.clone(),
        events: boot.events.clone(),
        actor: Actor::human(Surface::Gui),
        run: None,
        dry_run: false,
    };

    let backend_workspace = workspace.clone();
    let recorded = claim.clone();
    if let Some(port) = client {
        let _ = ready_tx.send(Ok(Bound {
            addr: std::net::SocketAddr::from(([127, 0, 0, 1], port)),
            token: String::new(),
            port,
        }));
    } else {
    std::thread::spawn(move || {
        let runtime = match tokio::runtime::Builder::new_multi_thread()
            .enable_all()
            .build()
        {
            Ok(runtime) => runtime,
            Err(e) => {
                let _ = ready_tx.send(Err(format!("cannot start the async runtime: {e}")));
                return;
            }
        };
        let tx = ready_tx.clone();
        let result = runtime.block_on(devd_server::serve_with(
            registry,
            ctx,
            Options {
                port: 0,
                extra_checks: Vec::new(),
                workspace: Some(backend_workspace),
                shutdown: Some(shutdown_rx),
                picker: Some(Arc::new(picker::NativePicker)),
            },
            move |bound| {
                if let Ok(mut held) = recorded.lock() {
                    if let Some(claim) = held.as_mut() {
                        let _ = claim.set_port(bound.port);
                    }
                }
                let _ = tx.send(Ok(bound.clone()));
            },
        ));
        if let Err(e) = result {
            let _ = ready_tx.send(Err(format!("the devd backend stopped: {e}")));
        }
    });
    }

    let startup = ready_rx
        .recv_timeout(Duration::from_secs(30))
        .unwrap_or_else(|_| Err("the devd backend did not become ready within 30 seconds".into()));
    match &startup {
        Ok(bound) => startup_log(&format!("backend ready on port {}", bound.port)),
        Err(e) => startup_log(&format!("backend did not start: {e}")),
    }

    let shutdown_for_window = shutdown.clone();
    let tray_ready_for_window = tray_ready.clone();
    let data_dir_for_tray = data_dir.clone();
    let builder = tauri::Builder::default()
        // Registered first: a second launch focuses the window that is already
        // running and exits, so there is one tray icon and one backend.
        .plugin(tauri_plugin_single_instance::init(|app, _argv, _cwd| {
            show_main(app);
        }))
        .setup(move |app| {
        let window = match startup {
            Ok(bound) => {
                let origin = format!("http://127.0.0.1:{}", bound.port);
                let url: tauri::Url = origin.parse().expect("the loopback URL is valid");
                let port = bound.port;
                let token = bound.token.clone();
                BACKEND_PORT.store(port, Ordering::SeqCst);
                match install_tray(
                    app,
                    port,
                    token,
                    data_dir_for_tray.clone(),
                    tray_projects.clone(),
                    tray_sites.clone(),
                    tray_services.clone(),
                ) {
                    Ok(()) => {
                        tray_ready_for_window.store(true, Ordering::SeqCst);
                        startup_log("tray icon ready");
                    }
                    Err(e) => startup_log(&format!("tray icon unavailable: {e}")),
                }
                WebviewWindowBuilder::new(app, "main", WebviewUrl::External(url))
                    .title("devd")
                    // Big enough for the three-column workspace, small enough
                    // that the same responsive UI is reachable by resizing the
                    // native window on a laptop.
                    .inner_size(1360.0, 900.0)
                    .min_inner_size(720.0, 520.0)
                    .theme(Some(tauri::Theme::Dark))
                    .center()
                    .on_navigation(move |url| {
                        let text = url.as_str();
                        let local = text.starts_with(&format!("http://127.0.0.1:{port}"))
                            || text.starts_with(&format!("http://localhost:{port}"))
                            || text.starts_with(&format!("http://[::1]:{port}"));
                        if local {
                            return true;
                        }
                        if text.starts_with("http://") || text.starts_with("https://") {
                            let _ = open::that(text);
                        }
                        false
                    })
                    .build()?
            }
            Err(message) => {
                let window = WebviewWindowBuilder::new(
                    app,
                    "main",
                    WebviewUrl::External("about:blank".parse().expect("about:blank is valid")),
                )
                .title("devd — backend error")
                .inner_size(760.0, 420.0)
                .center()
                .build()?;
                let body = serde_json::to_string(&explain(&message)).unwrap_or_else(|_| "\"backend error\"".into());
                let script = format!(
                    "document.body.style.cssText='font:14px ui-monospace,Consolas,monospace;background:#0a0a0b;color:#e8e6e3;padding:32px;white-space:pre-wrap';document.body.textContent={body};"
                );
                let _ = window.eval(&script);
                window
            }
        };
        // Started by the system at login: the tray is the way in, not a window
        // over whatever the person opened first.
        if !std::env::args().any(|a| a == "--start-hidden") {
            let _ = window.show();
        }
        Ok(())
    });

    let shutdown_for_event = shutdown.clone();
    let tray_ready_for_event = tray_ready.clone();
    let app = builder
        .on_window_event(move |window, event| {
            if let tauri::WindowEvent::CloseRequested { api, .. } = event {
                // Closing the window puts devd in the hidden-icons tray, not out
                // of the person's session. Quit is the tray menu's explicit act.
                if tray_ready_for_event.load(Ordering::SeqCst) {
                    api.prevent_close();
                    let _ = window.hide();
                } else {
                    send_shutdown(&shutdown_for_event);
                }
            }
        })
        .build(tauri::generate_context!())?;

    app.run(move |_app, event| {
        if matches!(event, RunEvent::Exit | RunEvent::ExitRequested { .. }) {
            send_shutdown(&shutdown_for_window);
        }
    });

    send_shutdown(&shutdown);
    if client.is_none() {
        workspace.shutdown();
    }
    if let Ok(mut held) = claim.lock() {
        held.take();
    }
    // Give the server thread a moment to drop the AppState, which stops PTYs and
    // removes its process trees before the process image disappears.
    std::thread::sleep(Duration::from_millis(250));
    Ok(())
}

/// Put the devd window in front, restoring it from the tray or a minimised state.
/// The port the backend ended up on, so a window reopened after a restart can
/// find it again instead of holding an address nothing answers on.
static BACKEND_PORT: AtomicU16 = AtomicU16::new(0);

/// Call one capability on the local API with the session token. The tray's
/// actions are the same calls the window makes, so they are checked and audited
/// the same way.
fn api_call(port: u16, token: &str, id: &str, args: serde_json::Value) -> Option<serde_json::Value> {
    if token.is_empty() {
        return None;
    }
    let body = serde_json::json!({ "id": id, "args": args, "dry_run": false }).to_string();
    let response = ureq::post(&format!("http://127.0.0.1:{port}/api/invoke"))
        .set("Authorization", &format!("Bearer {token}"))
        .set("Content-Type", "application/json")
        .send_string(&body)
        .ok()?;
    serde_json::from_str::<serde_json::Value>(&response.into_string().ok()?).ok()
}

fn show_main(app: &tauri::AppHandle) {
    if let Some(window) = app.get_webview_window("main") {
        let _ = window.show();
        let _ = window.unminimize();
        let _ = window.set_focus();
        let port = BACKEND_PORT.load(Ordering::SeqCst);
        if port > 0 {
            // If the window is on an old port, go to the live one. If it is on
            // the right port but showing the browser's network-error page (the
            // backend had not answered when it was reopened), reload it. A
            // working conversation is left exactly as it is.
            let script = format!(
                "try{{if(location.port&&location.port!=='{port}'&&location.hostname!==''){{location.replace('http://127.0.0.1:{port}/')}}else if(document.body&&/can.t be reached|ERR_CONNECTION|This page isn.t working/i.test(document.body.innerText)){{location.reload()}}}}catch(e){{}}"
            );
            let _ = window.eval(&script);
        }
    }
}

/// Whether devd is registered to start when the person signs in.
fn autostart_on() -> bool {
    #[cfg(windows)]
    {
        let out = std::process::Command::new("reg.exe")
            .args([
                "query",
                r"HKCU\Software\Microsoft\Windows\CurrentVersion\Run",
                "/v",
                "devd",
            ])
            .output();
        matches!(out, Ok(o) if o.status.success())
    }
    #[cfg(not(windows))]
    {
        false
    }
}

/// Register or unregister devd's start-at-login entry.
///
/// Windows reads the per-user Run key; the entry starts the desktop shell with
/// `--start-hidden`, so signing in puts devd in the tray rather than a window
/// over the desktop. Other desktops have their own autostart mechanism, so the
/// menu entry is left off there.
fn set_autostart(on: bool) {
    #[cfg(windows)]
    {
        let Ok(exe) = std::env::current_exe() else {
            return;
        };
        let key = r"HKCU\Software\Microsoft\Windows\CurrentVersion\Run";
        let mut command = std::process::Command::new("reg.exe");
        if on {
            command.args([
                "add",
                key,
                "/v",
                "devd",
                "/t",
                "REG_SZ",
                "/d",
                &format!("\"{}\" --start-hidden", exe.display()),
                "/f",
            ]);
        } else {
            command.args(["delete", key, "/v", "devd", "/f"]);
        }
        let _ = command.output();
    }
    #[cfg(not(windows))]
    {
        let _ = on;
    }
}

/// What the tray lists that does not change while the process runs.
#[derive(Clone)]
struct TrayState {
    port: u16,
    token: String,
    data_dir: String,
    projects: Vec<(String, String)>,
    sites: Vec<(String, String)>,
    services: Vec<String>,
}

/// What the tray shows that does change: service state, open shares, and the
/// incidents self-healing has recorded. Refreshed from the same API the window
/// uses, so the menu cannot claim something the backend disagrees with.
#[derive(Clone, Default, PartialEq)]
struct TrayLive {
    /// name, running, ready
    services: Vec<(String, bool, bool)>,
    /// project, public address
    links: Vec<(String, String)>,
    /// "kind: service — detail"
    incidents: Vec<String>,
}

fn live_from_api(state: &TrayState) -> TrayLive {
    let mut live = TrayLive::default();
    // One read for every service, rather than a probe per menu row. This is the
    // same call the services screen makes and it carries installed, running and
    // ready together.
    let listed = api_call(
        state.port,
        &state.token,
        "service.list",
        serde_json::json!({}),
    );
    let data = listed
        .as_ref()
        .and_then(|v| v.get("outcome"))
        .and_then(|o| o.get("data"));
    let items = data
        .and_then(|d| d.as_array())
        .or_else(|| data.and_then(|d| d.get("services")).and_then(|v| v.as_array()));
    let mut known: Vec<(String, bool, bool)> = Vec::new();
    for row in items.into_iter().flatten() {
        if let Some(name) = row["name"].as_str() {
            known.push((
                name.to_string(),
                row["running"].as_bool().unwrap_or(false),
                row["ready"].as_bool().unwrap_or(false),
            ));
        }
    }
    for name in &state.services {
        match known.iter().find(|(n, _, _)| n == name) {
            Some((_, running, ready)) => live.services.push((name.clone(), *running, *ready)),
            None => live.services.push((name.clone(), false, false)),
        }
    }
    if let Some(d) = api_call(
        state.port,
        &state.token,
        "share.quick",
        serde_json::json!({}),
    )
    .as_ref()
    .and_then(|v| v.get("outcome"))
    .and_then(|o| o.get("data"))
    {
        for link in d["links"].as_array().into_iter().flatten() {
            if let (Some(project), Some(url)) = (link["project"].as_str(), link["url"].as_str()) {
                live.links.push((project.to_string(), url.to_string()));
            }
        }
    }
    if let Some(d) = api_call(
        state.port,
        &state.token,
        "health.status",
        serde_json::json!({}),
    )
    .as_ref()
    .and_then(|v| v.get("outcome"))
    .and_then(|o| o.get("data"))
    {
        for row in d["incidents"]
            .as_array()
            .into_iter()
            .flatten()
            .rev()
            .take(5)
        {
            let kind = row["kind"].as_str().unwrap_or("incident");
            let service = row["service"].as_str().unwrap_or("");
            let detail = row["detail"].as_str().unwrap_or("");
            live.incidents.push(format!("{kind}: {service} — {detail}"));
        }
    }
    live
}

/// Build the menu from a state snapshot. Called once at startup and again
/// whenever the live snapshot changes, so a stopped service offers Start and a
/// running one offers Stop instead of both being decoration.
fn tray_menu(
    app: &tauri::AppHandle,
    state: &TrayState,
    live: &TrayLive,
) -> tauri::Result<Menu<Wry>> {
    let base = format!("http://127.0.0.1:{}", state.port);
    let running = live.services.iter().filter(|(_, run, _)| *run).count();
    let summary = if !live.incidents.is_empty() {
        format!("{} incident(s)", live.incidents.len())
    } else if !live.services.is_empty() {
        format!("{running}/{} service(s) running", live.services.len())
    } else {
        "healthy".to_string()
    };
    let title = MenuItem::with_id(
        app,
        "title",
        format!("devd {}  ·  {summary}  ·  {base}", env!("CARGO_PKG_VERSION")),
        false,
        None::<&str>,
    )?;
    let open = MenuItem::with_id(app, "open", "Open devd", true, None::<&str>)?;
    let assistant = MenuItem::with_id(app, "assistant", "Open Assistant", true, None::<&str>)?;
    let runs = MenuItem::with_id(app, "runs", "Open agent runs", true, None::<&str>)?;
    let browser = MenuItem::with_id(app, "browser", "Open in browser", true, None::<&str>)?;

    // Health: the cause and what self-healing did, not just a count. The row is
    // always present so its absence never looks like "not checked".
    let health = {
        let mut rows: Vec<MenuItem<Wry>> = Vec::new();
        if live.incidents.is_empty() {
            rows.push(MenuItem::with_id(
                app,
                "health:none",
                "No incidents; services answer",
                false,
                None::<&str>,
            )?);
        }
        for (i, text) in live.incidents.iter().enumerate() {
            rows.push(MenuItem::with_id(
                app,
                format!("health:{i}"),
                text.as_str(),
                false,
                None::<&str>,
            )?);
        }
        rows.push(MenuItem::with_id(
            app,
            "health:page",
            "Open Diagnostics",
            true,
            None::<&str>,
        )?);
        let label = if live.incidents.is_empty() {
            "Health · healthy".to_string()
        } else {
            format!("Health · {} incident(s)", live.incidents.len())
        };
        let refs: Vec<&dyn IsMenuItem<Wry>> = rows.iter().map(|i| i as &dyn IsMenuItem<Wry>).collect();
        Some(Submenu::with_items(app, label, true, &refs)?)
    };

    // www: the projects devd knows, each opening its folder.
    let mut www_items = vec![MenuItem::with_id(app, "www:page", "Open projects", true, None::<&str>)?];
    if state.projects.is_empty() {
        www_items.push(MenuItem::with_id(app, "www:none", "No projects yet", false, None::<&str>)?);
    }
    for (i, (name, _)) in state.projects.iter().enumerate() {
        www_items.push(MenuItem::with_id(app, format!("www:{i}"), name.as_str(), true, None::<&str>)?);
    }
    let www_refs: Vec<&dyn IsMenuItem<Wry>> = www_items.iter().map(|i| i as &dyn IsMenuItem<Wry>).collect();
    let www = Submenu::with_items(app, "www", true, &www_refs)?;

    // Quick Share: open links first, with their real addresses and a Stop.
    let share = {
        let mut rows: Vec<MenuItem<Wry>> = vec![
            MenuItem::with_id(app, "share:page", "Manage sharing", true, None::<&str>)?,
        ];
        if !live.links.is_empty() {
            for (i, (project, url)) in live.links.iter().enumerate() {
                rows.push(MenuItem::with_id(
                    app,
                    format!("share:open:{i}"),
                    format!("Open {project} · {url}"),
                    true,
                    None::<&str>,
                )?);
                rows.push(MenuItem::with_id(
                    app,
                    format!("share:stop:{i}"),
                    format!("Stop sharing {project}"),
                    true,
                    None::<&str>,
                )?);
            }
        }
        if state.sites.is_empty() {
            rows.push(MenuItem::with_id(app, "share:none", "No sites to share", false, None::<&str>)?);
        }
        for (i, (name, _)) in state.sites.iter().enumerate() {
            rows.push(MenuItem::with_id(app, format!("share:{i}"), format!("Share {name}"), true, None::<&str>)?);
        }
        let label = if live.links.is_empty() {
            "Quick Share".to_string()
        } else {
            format!("Quick Share · {} active", live.links.len())
        };
        let refs: Vec<&dyn IsMenuItem<Wry>> = rows.iter().map(|i| i as &dyn IsMenuItem<Wry>).collect();
        Submenu::with_items(app, label, true, &refs)?
    };

    // Services: each one names its actual state, and its Start/Stop entries
    // are only usable when they would do something.
    let services_menu = {
        let mut subs: Vec<Submenu<Wry>> = Vec::new();
        for name in &state.services {
            let found = live.services.iter().find(|(n, _, _)| n == name);
            let (is_running, is_ready) = match found {
                Some((_, run, ready)) => (*run, *ready),
                None => (false, false),
            };
            let state_text = if !is_running {
                "stopped"
            } else if is_ready {
                "running"
            } else {
                "running, not answering"
            };
            let mut items = vec![MenuItem::with_id(
                app,
                format!("svc:{name}:state"),
                state_text,
                false,
                None::<&str>,
            )?];
            items.push(MenuItem::with_id(app, format!("svc:{name}:start"), "Start", !is_running, None::<&str>)?);
            items.push(MenuItem::with_id(app, format!("svc:{name}:stop"), "Stop", is_running, None::<&str>)?);
            items.push(MenuItem::with_id(app, format!("svc:{name}:restart"), "Restart", is_running, None::<&str>)?);
            items.push(MenuItem::with_id(app, format!("svc:{name}:logs"), "Logs", true, None::<&str>)?);
            let refs: Vec<&dyn IsMenuItem<Wry>> = items.iter().map(|i| i as &dyn IsMenuItem<Wry>).collect();
            subs.push(Submenu::with_items(app, format!("{name} · {state_text}"), true, &refs)?);
        }
        let mut head = vec![
            MenuItem::with_id(app, "svc:page", "Open services", true, None::<&str>)?,
            MenuItem::with_id(app, "svc:add", "Add or register a service…", true, None::<&str>)?,
        ];
        if subs.is_empty() {
            head.push(MenuItem::with_id(app, "svc:none", "No services installed", false, None::<&str>)?);
        }
        let mut refs: Vec<&dyn IsMenuItem<Wry>> = head.iter().map(|i| i as &dyn IsMenuItem<Wry>).collect();
        refs.extend(subs.iter().map(|s| s as &dyn IsMenuItem<Wry>));
        Submenu::with_items(app, "Services", true, &refs)?
    };

    let start_all = MenuItem::with_id(
        app,
        "start-all",
        "Start All",
        running < state.services.len(),
        None::<&str>,
    )?;
    let stop_all = MenuItem::with_id(app, "stop-all", "Stop All", running > 0, None::<&str>)?;
    let quick_app = MenuItem::with_id(app, "create", "Quick app", true, None::<&str>)?;
    let terminal = MenuItem::with_id(app, "terminal", "Terminal", true, None::<&str>)?;
    let prefs = MenuItem::with_id(app, "prefs", "Preferences…", true, None::<&str>)?;
    let tools = Submenu::with_items(
        app,
        "Tools",
        true,
        &[
            &MenuItem::with_id(app, "tools:runtimes", "Runtimes and tools", true, None::<&str>)?,
            &MenuItem::with_id(app, "tools:models", "Models", true, None::<&str>)?,
            &MenuItem::with_id(app, "tools:activity", "Activity", true, None::<&str>)?,
            &MenuItem::with_id(app, "tools:diagnostics", "Diagnostics", true, None::<&str>)?,
            &MenuItem::with_id(app, "tools:api", "API and capabilities", true, None::<&str>)?,
        ],
    )?;

    let folder = MenuItem::with_id(app, "folder", "Open devd folder", true, None::<&str>)?;
    let projects_folder = MenuItem::with_id(app, "projects", "Open projects folder", true, None::<&str>)?;
    let log = MenuItem::with_id(app, "log", "Open desktop log", true, None::<&str>)?;
    let autostart = CheckMenuItem::with_id(
        app,
        "autostart",
        "Start at login",
        true,
        autostart_on(),
        None::<&str>,
    )?;
    let quit = MenuItem::with_id(app, "quit", "Quit devd", true, None::<&str>)?;
    let above = PredefinedMenuItem::separator(app)?;
    let below = PredefinedMenuItem::separator(app)?;
    let before_quit = PredefinedMenuItem::separator(app)?;
    let status_sep = PredefinedMenuItem::separator(app)?;

    let mut rows: Vec<&dyn IsMenuItem<Wry>> = vec![
        &title,
        &open,
        &assistant,
        &runs,
        &browser,
        &status_sep,
    ];
    if let Some(h) = health.as_ref() {
        rows.push(h);
    }
    rows.extend([
        &www as &dyn IsMenuItem<Wry>,
        &share,
        &services_menu,
        &start_all,
        &stop_all,
        &quick_app,
        &tools,
        &terminal,
        &prefs,
        &above,
        &folder,
        &projects_folder,
        &log,
        &below,
        &autostart,
        &before_quit,
        &quit,
    ]);
    Menu::with_items(app, &rows)
}

/// The hidden-icons tray and its menu.
///
/// Left click restores the window; right click opens the menu. The menu is
/// rebuilt from live state, so the actions it offers are the ones that would
/// work right now. Every action goes through the same capability API as the
/// window, so permissions, approvals and the audit trail are identical.
fn install_tray(
    app: &tauri::App,
    port: u16,
    token: String,
    data_dir: String,
    projects: Vec<(String, String)>,
    sites: Vec<(String, String)>,
    services: Vec<String>,
) -> tauri::Result<()> {
    let Some(icon) = app.default_window_icon().cloned() else {
        return Ok(());
    };
    let state = TrayState {
        port,
        token,
        data_dir,
        projects,
        sites,
        services,
    };
    let base = format!("http://127.0.0.1:{port}");
    let live = Arc::new(Mutex::new(live_from_api(&state)));
    let initial = live.lock().map(|l| l.clone()).unwrap_or_default();
    let menu = tray_menu(app.handle(), &state, &initial)?;

    let state_for_menu = state.clone();
    let live_for_menu = live.clone();
    TrayIconBuilder::with_id("devd")
        .icon(icon)
        .tooltip(format!(
            "devd {} - running in the background",
            env!("CARGO_PKG_VERSION")
        ))
        .menu(&menu)
        // Right click is the menu; left click restores the window.
        .show_menu_on_left_click(false)
        .on_menu_event(move |app, event| {
            let id = event.id.as_ref().to_string();
            let port = state_for_menu.port;
            let token = state_for_menu.token.clone();
            let dir = state_for_menu.data_dir.clone();
            match id.as_str() {
                "open" => show_main(app),
                "assistant" => {
                    let _ = open::that(format!("{base}/assistant"));
                }
                "runs" => {
                    let _ = open::that(format!("{base}/agents/runs"));
                }
                "browser" => {
                    let _ = open::that(&base);
                }
                "www:page" => {
                    let _ = open::that(format!("{base}/projects"));
                }
                "share:page" => {
                    let _ = open::that(format!("{base}/sites"));
                }
                "svc:page" => {
                    let _ = open::that(format!("{base}/server/services"));
                }
                "svc:add" => {
                    // Installing or adopting a service is a decision with its
                    // own screen and options, not a menu toggle.
                    let _ = open::that(format!("{base}/server/services"));
                }
                "health:page" => {
                    let _ = open::that(format!("{base}/diagnostics"));
                }
                "create" => {
                    let _ = open::that(format!("{base}/create"));
                }
                "terminal" => {
                    let _ = open::that(format!("{base}/terminal"));
                }
                "prefs" => {
                    let _ = open::that(format!("{base}/diagnostics"));
                }
                "tools:runtimes" => {
                    let _ = open::that(format!("{base}/server/runtimes"));
                }
                "tools:diagnostics" => {
                    let _ = open::that(format!("{base}/diagnostics"));
                }
                "tools:models" => {
                    let _ = open::that(format!("{base}/models"));
                }
                "tools:activity" => {
                    let _ = open::that(format!("{base}/activity"));
                }
                "tools:api" => {
                    let _ = open::that(format!("{base}/api-tools"));
                }
                // A menu handler must return at once; starting services and
                // tunnels takes seconds, so those calls run on a thread.
                // stack.up / stack.down respect dependency order and only act on
                // services devd manages.
                "start-all" => {
                    std::thread::spawn(move || {
                        let _ = api_call(port, &token, "stack.up", serde_json::json!({}));
                    });
                }
                "stop-all" => {
                    std::thread::spawn(move || {
                        let _ = api_call(port, &token, "stack.down", serde_json::json!({}));
                    });
                }
                "folder" => {
                    let _ = open::that(&dir);
                }
                "projects" => {
                    let www = std::path::PathBuf::from(&dir).join("www");
                    let _ = open::that(if www.is_dir() {
                        www
                    } else {
                        std::path::PathBuf::from(&dir)
                    });
                }
                "log" => {
                    let file = std::path::PathBuf::from(&dir).join("desktop.log");
                    if file.exists() {
                        let _ = open::that(file);
                    } else {
                        let _ = open::that(&dir);
                    }
                }
                // The registry entry is the setting; the rebuilt menu shows the
                // check box from what the registry actually says.
                "autostart" => set_autostart(!autostart_on()),
                "quit" => app.exit(0),
                other => {
                    if let Some(rest) = other.strip_prefix("www:") {
                        if let Ok(i) = rest.parse::<usize>() {
                            if let Some((_, path)) = state_for_menu.projects.get(i) {
                                let _ = open::that(path);
                            }
                        }
                    } else if let Some(rest) = other.strip_prefix("share:open:") {
                        if let Ok(i) = rest.parse::<usize>() {
                            if let Ok(held) = live_for_menu.lock() {
                                if let Some((_, url)) = held.links.get(i) {
                                    let _ = open::that(url);
                                }
                            }
                        }
                    } else if let Some(rest) = other.strip_prefix("share:stop:") {
                        if let Ok(i) = rest.parse::<usize>() {
                            let project = live_for_menu
                                .lock()
                                .ok()
                                .and_then(|held| held.links.get(i).map(|(p, _)| p.clone()));
                            if let Some(project) = project {
                                let token = token.clone();
                                std::thread::spawn(move || {
                                    let _ = api_call(
                                        port,
                                        &token,
                                        "share.ngrok_stop",
                                        serde_json::json!({ "project": project }),
                                    );
                                });
                            }
                        }
                    } else if let Some(rest) = other.strip_prefix("share:") {
                        if let Ok(i) = rest.parse::<usize>() {
                            if let Some((_, root)) = state_for_menu.sites.get(i) {
                                let root = root.clone();
                                let token = token.clone();
                                let sites_url = format!("{base}/sites");
                                std::thread::spawn(move || {
                                    let started = api_call(
                                        port,
                                        &token,
                                        "share.ngrok_start",
                                        serde_json::json!({ "project": root }),
                                    );
                                    let url = started
                                        .as_ref()
                                        .and_then(|v| v["outcome"]["data"]["url"].as_str())
                                        .map(|u| u.to_string());
                                    match url {
                                        Some(url) => {
                                            let _ = open::that(url);
                                        }
                                        // Setup or a refusal: show the panel that explains it.
                                        None => {
                                            let _ = open::that(sites_url);
                                        }
                                    }
                                });
                            }
                        }
                    } else if let Some(rest) = other.strip_prefix("svc:") {
                        let mut parts = rest.splitn(2, ':');
                        let name = parts.next().unwrap_or("").to_string();
                        let action = parts.next().unwrap_or("").to_string();
                        if action == "logs" {
                            let _ = open::that(format!("{base}/server/services"));
                        } else if matches!(action.as_str(), "start" | "stop" | "restart") && !name.is_empty() {
                            let token = token.clone();
                            std::thread::spawn(move || {
                                let _ = api_call(
                                    port,
                                    &token,
                                    &format!("service.{action}"),
                                    serde_json::json!({ "name": name }),
                                );
                            });
                        }
                    }
                }
            }
        })
        .on_tray_icon_event(|tray, event| {
            if let TrayIconEvent::Click {
                button: MouseButton::Left,
                button_state: MouseButtonState::Up,
                ..
            } = event
            {
                show_main(tray.app_handle());
            }
        })
        .build(app)?;

    // Keep the menu truthful. Thirty seconds is fast enough to notice a service
    // going down and slow enough that the probes are not a background load.
    let handle = app.handle().clone();
    let refresh_state = state.clone();
    let refresh_live = live.clone();
    let _ = std::thread::Builder::new()
        .name("devd-tray-refresh".into())
        .spawn(move || loop {
            std::thread::sleep(Duration::from_secs(30));
            let live = live_from_api(&refresh_state);
            // Replacing the menu closes it if it is open, and rebuilding costs
            // native menu objects. Only do that when something a person can see
            // has actually changed.
            let changed = match refresh_live.lock() {
                Ok(held) if *held == live => false,
                Ok(mut held) => {
                    *held = live.clone();
                    true
                }
                Err(_) => true,
            };
            if !changed {
                continue;
            }
            let thread_handle = handle.clone();
            let state = refresh_state.clone();
            let _ = handle.run_on_main_thread(move || {
                let handle = thread_handle;
                let Some(tray) = handle.tray_by_id("devd") else {
                    return;
                };
                if let Ok(menu) = tray_menu(&handle, &state, &live) {
                    let _ = tray.set_menu(Some(menu));
                }
                let running = live.services.iter().filter(|(_, run, _)| *run).count();
                let tip = if live.incidents.is_empty() {
                    format!(
                        "devd {} - {} service(s) running",
                        env!("CARGO_PKG_VERSION"),
                        running
                    )
                } else {
                    format!(
                        "devd {} - {} incident(s)",
                        env!("CARGO_PKG_VERSION"),
                        live.incidents.len()
                    )
                };
                let _ = tray.set_tooltip(Some(&tip));
            });
        });
    Ok(())
}
fn send_shutdown(shutdown: &Shutdown) {
    if let Ok(guard) = shutdown.lock() {
        if let Some(tx) = guard.as_ref() {
            let _ = tx.send(true);
        }
    }
}

/// Say what a failure means, and what to do about it.
///
/// The one that matters is the WebView2 runtime: the window cannot be drawn
/// without it, and the error the webview returns is not something a person
/// can act on.
fn explain(message: &str) -> String {
    if message.to_lowercase().contains("webview2") {
        return "The devd window needs the Microsoft Edge WebView2 runtime, and it is not installed on this machine.\n\n\
                Install it with:\n  MicrosoftEdgeWebview2Setup.exe /silent /install\n\n\
                or download it from:\n  https://developer.microsoft.com/microsoft-edge/webview2/\n\n\
                The command line works without it: devd ui"
            .to_string();
    }
    message.to_string()
}

/// Show a startup failure without starting a backend.
fn show_error(message: String) {
    let shutdown: Shutdown = Arc::new(Mutex::new(None));
    let _ = tauri::Builder::default()
        .setup(move |app| {
            let window = WebviewWindowBuilder::new(
                app,
                "main",
                WebviewUrl::External("about:blank".parse().expect("about:blank is valid")),
            )
            .title("devd — startup error")
            .inner_size(760.0, 460.0)
            .center()
            .build()?;
            let body = serde_json::to_string(&message).unwrap_or_else(|_| "\"startup error\"".into());
            let script = format!(
                "document.body.style.cssText='font:14px ui-monospace,Consolas,monospace;background:#0a0a0b;color:#e8e6e3;padding:32px;white-space:pre-wrap';document.body.textContent={body};"
            );
            let _ = window.eval(&script);
            Ok(())
        })
        .on_window_event(move |_window, event| {
            if matches!(event, tauri::WindowEvent::CloseRequested { .. }) {
                send_shutdown(&shutdown);
            }
        })
        .run(tauri::generate_context!());
}
